import { useRef, useState } from 'react';
import { Download, Upload } from 'lucide-react';
import { downloadFile } from '../lib/format.js';
import { useAppStore } from '../lib/store.jsx';
export function SettingsPage(){const{state,commit,replaceState}=useAppStore();const[settings,setSettings]=useState(state.settings);const fileRef=useRef(null);const save=()=>commit(d=>{d.settings={...d.settings,...settings};});const backup=()=>downloadFile(`uffda-command-center-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(state,null,2),'application/json');const restore=async e=>{const file=e.target.files?.[0];if(!file)return;try{const parsed=JSON.parse(await file.text());if(!confirm('Replace current command-center data with this backup?'))return;replaceState(parsed);setSettings(parsed.settings||settings);}catch{alert('That file is not a valid command-center backup.');}finally{e.target.value='';}};return <div className="settings-grid"><section className="surface"><div className="section-head"><div><h2>Business defaults</h2><p>Defaults affect new entries only; saved daily reports retain their snapshots.</p></div></div><div className="form-grid compact"><Field label="Business name"><input value={settings.businessName} onChange={e=>setSettings({...settings,businessName:e.target.value})}/></Field><Field label="Currency"><select value={settings.currency} onChange={e=>setSettings({...settings,currency:e.target.value})}><option>USD</option></select></Field><Field label="Default processing %"><input inputMode="decimal" value={settings.defaultProcessingPct} onChange={e=>setSettings({...settings,defaultProcessingPct:e.target.value})}/></Field><Field label="Default fixed processing fee"><input inputMode="decimal" value={settings.defaultProcessingFixed} onChange={e=>setSettings({...settings,defaultProcessingFixed:e.target.value})}/></Field><Field label="Default daily overhead"><input inputMode="decimal" value={settings.defaultOverhead} onChange={e=>setSettings({...settings,defaultOverhead:e.target.value})}/></Field></div><div className="settings-actions"><button className="button primary" type="button" onClick={save}>Save settings</button></div></section><section className="surface"><div className="section-head"><div><h2>Data portability</h2><p>Browser-local data should be backed up regularly.</p></div></div><div className="backup-panel"><button className="button secondary" type="button" onClick={backup}><Download size={16}/> Download JSON backup</button><button className="button secondary" type="button" onClick={()=>fileRef.current?.click()}><Upload size={16}/> Restore backup</button><input ref={fileRef} type="file" accept="application/json,.json" hidden onChange={restore}/><p>Current schema: v{state.meta.schemaVersion} · revision {state.meta.revision}</p></div></section></div>;}
function Field({label,children}){return <label className="field"><span>{label}</span>{children}</label>;}
