import { AlertTriangle, ArrowUpRight, CheckCircle2 } from 'lucide-react';
import { formatMoney } from '../lib/finance.js';
import { formatDate, numberValue, percent, today } from '../lib/format.js';
import { useAppStore } from '../lib/store.jsx';
function Metric({label,value,note,tone=''}){return <article className={`metric-card ${tone}`}><span>{label}</span><strong>{value}</strong><small>{note}</small></article>;}
export function DashboardPage({onNavigate}){const{state}=useAppStore();const month=today().slice(0,7);const monthRows=state.dailyReports.filter(r=>r.date?.startsWith(month));const todayRow=state.dailyReports.find(r=>r.date===today());const sum=key=>monthRows.reduce((t,r)=>t+Number(r.summary?.[key]||0),0);const revenue=sum('revenueCents');const profit=sum('operatingProfitCents');const margin=revenue?(profit/revenue)*100:0;const low=state.inventory.filter(i=>numberValue(i.qty)<=numberValue(i.reorder)).slice(0,5);const recent=[...state.dailyReports].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,6);return <><section className="metric-grid"><Metric label="Today profit" value={formatMoney(todayRow?.summary?.operatingProfitCents||0,state.settings.currency)} note="Saved daily ledger" tone={(todayRow?.summary?.operatingProfitCents||0)>=0?'positive':'negative'}/><Metric label="Month revenue" value={formatMoney(revenue,state.settings.currency)} note={`${monthRows.length} saved service day${monthRows.length===1?'':'s'}`}/><Metric label="Month profit" value={formatMoney(profit,state.settings.currency)} note={`${percent(margin)} operating margin`} tone={profit>=0?'positive':'negative'}/><Metric label="Cost library" value={String(state.ingredients.filter(i=>i.active!==false).length)} note="Active costed inputs"/></section><section className="dashboard-grid"><div className="surface span-2"><div className="section-head"><div><h2>Recent service days</h2><p>Finalized ledgers retain their original cost snapshots.</p></div><button className="text-button" type="button" onClick={()=>onNavigate('daily')}>New entry <ArrowUpRight size={15}/></button></div>{recent.length?<div className="ledger-list">{recent.map(r=><button className="ledger-row" key={r.id} type="button" onClick={()=>onNavigate('reports')}><div><strong>{formatDate(r.date)}</strong><span>{r.location||'Service day'}</span></div><div className="ledger-numbers"><span>{formatMoney(r.summary?.revenueCents||0,state.settings.currency)}</span><strong className={(r.summary?.operatingProfitCents||0)>=0?'money-positive':'money-negative'}>{formatMoney(r.summary?.operatingProfitCents||0,state.settings.currency)}</strong></div></button>)}</div>:<div className="empty-state"><strong>No daily reports yet</strong><p>Configure your cost library, then save the first service day.</p></div>}</div><div className="surface"><div className="section-head"><div><h2>Attention</h2><p>Operational exceptions worth reviewing.</p></div></div><div className="attention-list">{low.length?low.map(i=><div className="attention-row warning" key={i.id}><AlertTriangle size={18}/><div><strong>{i.item}</strong><span>{i.qty} {i.unit||''} on hand · reorder at {i.reorder}</span></div></div>):<div className="attention-row success"><CheckCircle2 size={18}/><div><strong>Inventory levels</strong><span>No reorder alerts right now.</span></div></div>}<div className={`attention-row ${state.ingredients.length?'success':'warning'}`}>{state.ingredients.length?<CheckCircle2 size={18}/>:<AlertTriangle size={18}/>}<div><strong>Cost basis</strong><span>{state.ingredients.length?`${state.ingredients.filter(i=>i.active!==false).length} active inputs configured.`:'Add cost items before relying on daily profitability.'}</span></div></div></div></div></section></>;}
