import { X } from 'lucide-react';
export function Modal({title,description,children,actions,onClose}){return <div className="modal-backdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header className="modal-head"><div><h2 id="modal-title">{title}</h2>{description?<p>{description}</p>:null}</div><button className="icon-button" type="button" onClick={onClose} aria-label="Close dialog"><X size={18}/></button></header><div className="modal-body">{children}</div>{actions?<footer className="modal-actions">{actions}</footer>:null}</section></div>;}
