import { useMemo, useState } from 'react';
import { BarChart3, BookOpen, CalendarDays, ChevronRight, ClipboardCheck, ClipboardList, Cloud, Gauge, Menu, Package, Receipt, Settings, ShoppingBasket, Truck, Users, UtensilsCrossed, WalletCards, X } from 'lucide-react';
import { LABELS, NAV_GROUPS } from '../config/modules.js';
import { useAppStore } from '../lib/store.jsx';
const ICONS={dashboard:Gauge,daily:ClipboardCheck,costs:BookOpen,reports:BarChart3,sales:WalletCards,events:CalendarDays,customers:Users,inventory:Package,menu:UtensilsCrossed,purchases:ShoppingBasket,labor:ClipboardList,expenses:Receipt,vendors:Truck,settings:Settings};
export function Shell({route,onNavigate,title,subtitle,primaryAction,children}){const{state}=useAppStore();const[mobileOpen,setMobileOpen]=useState(false);const nav=useMemo(()=>NAV_GROUPS,[]);const navigate=key=>{setMobileOpen(false);onNavigate(key);};return <div className="app-layout"><aside className={`sidebar ${mobileOpen?'is-open':''}`}><div className="brand-row"><img className="brand-logo" src="/brand/uff-da-logo-white.webp" alt="Uff-Da Eats"/><button className="icon-button sidebar-close" type="button" onClick={()=>setMobileOpen(false)} aria-label="Close navigation"><X size={18}/></button></div><div className="brand-title"><strong>{state.settings.businessName}</strong><span>Command Center</span></div><nav className="navigation" aria-label="Primary">{nav.map(([group,keys])=><div className="nav-group" key={group}><div className="nav-caption">{group}</div>{keys.map(key=>{const Icon=ICONS[key]||ChevronRight;return <button key={key} type="button" className={`nav-item ${route===key?'active':''}`} onClick={()=>navigate(key)}><Icon size={17}/><span>{LABELS[key]}</span></button>;})}</div>)}</nav><div className="sidebar-foot"><span className="pine-line"/><span>Good food. Further together.</span></div></aside><main className="main-shell"><header className="topbar"><button className="icon-button mobile-menu" type="button" onClick={()=>setMobileOpen(true)} aria-label="Open navigation"><Menu size={20}/></button><div className="page-heading"><span className="page-brand">Uff-Da Eats</span><h1>{title}</h1><p>{subtitle}</p></div><div className="top-actions">{primaryAction}<span className="sync-state"><Cloud size={15}/> Local</span></div></header><div className="content">{children}</div></main>{mobileOpen?<button className="mobile-scrim" type="button" aria-label="Close navigation" onClick={()=>setMobileOpen(false)}/>:null}</div>;}
