import { useMemo, useState } from 'react';
import { Download, Eye } from 'lucide-react';
import { Modal } from '../components/Modal.jsx';
import { formatMoney } from '../lib/finance.js';
import { downloadFile, formatDate, percent } from '../lib/format.js';
import { useAppStore } from '../lib/store.jsx';
export function ReportsPage(){const{state}=useAppStore();const[selected,setSelected]=useState(null);const rows=useMemo(()=>[...state.dailyReports].sort((a,b)=>b.date.localeCompare(a.date)),[state.dailyReports]);const totals=useMemo(()=>rows.reduce((a,r)=>({revenue:a.revenue+Number(r.summary?.revenueCents||0),profit:a.profit+Number(r.summary?.operatingProfitCents||0),cost:a.cost+Number(r.summary?.totalCostCents||0)}),{revenue:0,profit:0,cost:0}),[rows]);const exportCsv=()=>{const header=['Date','Location','Revenue','Food Cost','Packaging','Labor','Processing','Direct Expenses','Overhead','Total Cost','Profit','Margin %'];const data=rows.map(r=>[r.date,r.location||'',...['revenueCents','foodCostCents','packagingCostCents','laborCostCents','processingFeesCents','directExpensesCents','allocatedOverheadCents','totalCostCents','operatingProfitCents'].map(k=>(Number(r.summary?.[k]||0)/100).toFixed(2)),Number(r.summary?.marginPct||0).toFixed(2)]);const csv=[header,...data].map(record=>record.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\n');downloadFile('uffda-daily-profit-reports.csv',csv,'text/csv;charset=utf-8');};return <><section className="metric-grid three"><Metric label="Saved service days" value={String(rows.length)}/><Metric label="Recorded revenue" value={formatMoney(totals.revenue,state.settings.currency)}/><Metric label="Recorded profit" value={formatMoney(totals.profit,state.settings.currency)} tone={totals.profit>=0?'positive':'negative'}/></section><section className="surface"><div className="section-head"><div><h2>Job ledgers</h2><p>Finalized job counts retain their opening/ending inventory and original cost snapshots.</p></div><button className="button secondary" type="button" onClick={exportCsv} disabled={!rows.length}><Download size={16}/> Export CSV</button></div>{rows.length?<div className="table-scroll"><table className="data-table"><thead><tr><th>Date</th><th>Location</th><th>Revenue</th><th>Total cost</th><th>Profit</th><th>Margin</th><th></th></tr></thead><tbody>{rows.map(r=><tr key={r.id}><td>{formatDate(r.date)}</td><td>{r.location||'—'}</td><td>{formatMoney(r.summary?.revenueCents||0,state.settings.currency)}</td><td>{formatMoney(r.summary?.totalCostCents||0,state.settings.currency)}</td><td className={(r.summary?.operatingProfitCents||0)>=0?'money-positive':'money-negative'}>{formatMoney(r.summary?.operatingProfitCents||0,state.settings.currency)}</td><td>{percent(r.summary?.marginPct)}</td><td><button className="icon-button" type="button" onClick={()=>setSelected(r)} aria-label="View report"><Eye size={16}/></button></td></tr>)}</tbody></table></div>:<div className="empty-state"><strong>No reports saved</strong><p>Close a job inventory reconciliation to create the first ledger.</p></div>}</section>{selected?<Modal title={`${formatDate(selected.date)} report`} description={selected.location||'Service day'} onClose={()=>setSelected(null)} actions={<button className="button primary" type="button" onClick={()=>setSelected(null)}>Done</button>}><div className="report-detail-grid">{Object.entries({Revenue:selected.summary.revenueCents,'Food cost':selected.summary.foodCostCents,Packaging:selected.summary.packagingCostCents,Labor:selected.summary.laborCostCents,Processing:selected.summary.processingFeesCents,'Direct expenses':selected.summary.directExpensesCents,Overhead:selected.summary.allocatedOverheadCents,'Total cost':selected.summary.totalCostCents,Profit:selected.summary.operatingProfitCents}).map(([label,value])=><div key={label}><span>{label}</span><strong>{formatMoney(value||0,state.settings.currency)}</strong></div>)}</div><h3 className="detail-heading">Item-by-item reconciliation</h3>{selected.reconciliation?.length?<div className="usage-detail-list">{selected.reconciliation.map(item=><div key={`${item.ingredientId}-${item.name}`}><div><strong>{item.name}</strong><span>Start {item.startQty} + added {item.additionsQty} − end {item.endQty} = {item.depletedQty} depleted · {item.serviceQty} {item.trackingType==='direct-sale'?'sold':'service use'} · {item.wasteQty} waste · {item.compQty} comp {item.unit}</span></div><strong>{formatMoney(item.totalCostCents||0,state.settings.currency)}</strong></div>)}</div>:selected.usages?.length?<div className="usage-detail-list">{selected.usages.map(item=><div key={`${item.ingredientId}-${item.name}`}><div><strong>{item.name}</strong><span>{item.soldQty} {item.trackingType==='direct-sale'?'sold':'service use'} · {item.wasteQty} waste · {item.compQty} comp {item.unit}</span></div><strong>{formatMoney(item.totalCostCents||0,state.settings.currency)}</strong></div>)}</div>:<p className="muted">No measured usage was recorded.</p>}</Modal>:null}</>;}
function Metric({label,value,tone=''}){return <article className={`metric-card ${tone}`}><span>{label}</span><strong>{value}</strong></article>;}
